57	func TestListModels_providerTypesOpenRouterLMStudioOMLXVLLMRapidMLX(t *testing.T) {
58		openrouter := fakeModelsServer([]string{"openrouter/model-a"})
59		defer openrouter.Close()
60		lmstudio := fakeModelsServer([]string{"lmstudio-model-a"})
61		defer lmstudio.Close()
62		omlx := fakeModelsServer([]string{"omlx-model-a"})
63		defer omlx.Close()
64		vllm := fakeModelsServer([]string{"vllm-model-a"})
65		defer vllm.Close()
66		rapidmlx := fakeModelsServer([]string{"rapid-mlx-model-a"})
67		defer rapidmlx.Close()
68	
69		sc := &fakeServiceConfig{
70			providers: map[string]ServiceProviderEntry{
71				"openrouter": {Type: "openrouter", BaseURL: openrouter.URL + "/api/v1"},
72				"studio":     {Type: "lmstudio", BaseURL: lmstudio.URL + "/v1"},
73				"vidar-omlx": {Type: "omlx", BaseURL: omlx.URL + "/v1"},
74				"sindri":     {Type: "vllm", BaseURL: vllm.URL + "/v1"},
75				"grendel":    {Type: "rapid-mlx", BaseURL: rapidmlx.URL + "/v1"},
76			},
77			names:       []string{"openrouter", "studio", "vidar-omlx", "sindri", "grendel"},
78			defaultName: "openrouter",
79		}
80		svc := newTestService(t, ServiceOptions{ServiceConfig: sc})
81	
82		infos, err := svc.ListModels(context.Background(), ModelFilter{})
83		if err != nil {
84			t.Fatalf("ListModels: %v", err)
85		}
86		if len(infos) != 5 {
87			t.Fatalf("want 5 models, got %d: %v", len(infos), modelIDs(infos))
88		}
89	
90		wantTypes := map[string]string{
91			"openrouter": "openrouter",
92			"studio":     "lmstudio",
93			"vidar-omlx": "omlx",
94			"sindri":     "vllm",
95			"grendel":    "rapid-mlx",
96		}
97		for _, info := range infos {
98			if info.ProviderType != wantTypes[info.Provider] {
99				t.Errorf("provider %q type=%q, want %q", info.Provider, info.ProviderType, wantTypes[info.Provider])
100			}
101			if info.EndpointName == "" {
102				t.Errorf("provider %q model %q missing EndpointName", info.Provider, info.ID)
103			}
104			if info.EndpointBaseURL == "" {
105				t.Errorf("provider %q model %q missing EndpointBaseURL", info.Provider, info.ID)
106			}
107			if got := serverinstance.FromBaseURL(info.EndpointBaseURL); info.ServerInstance != got {
108				t.Errorf("provider %q model %q server instance = %q, want %q", info.Provider, info.ID, info.ServerInstance, got)
109			}
110		}
111	}
