653	// stubSubscriptionHarnessLookPath makes the given binaries discoverable via the
654	// registry's LookPath seam and reports every other binary as missing, so the
655	// test is hermetic regardless of which CLIs are installed on the host.
656	func stubSubscriptionHarnessLookPath(svc *service, available ...string) {
657		set := make(map[string]struct{}, len(available))
658		for _, name := range available {
659			set[name] = struct{}{}
660		}
661		svc.registry.LookPath = func(file string) (string, error) {
662			if _, ok := set[file]; ok {
663				return "/usr/local/bin/" + file, nil
664			}
665			return "", exec.ErrNotFound
666		}
667	}
668	
669	// stubSubprocessHarnessModelIDs replaces the package-level model-ID resolver
670	// with a hermetic map for the duration of the test, so the subscription-tier
671	// surface does not depend on launching real CLIs via PTY (which requires an
672	// interactive TTY unavailable in CI/sandboxes).
673	func stubSubprocessHarnessModelIDs(t *testing.T, byHarness map[string][]string) {
674		t.Helper()
675		prev := subprocessHarnessModelIDs
676		t.Cleanup(func() { subprocessHarnessModelIDs = prev })
677		subprocessHarnessModelIDs = func(name string, _ harnesses.HarnessConfig) []string {
678			return byHarness[name]
679		}
680	}
