51	func structHasField(t *testing.T, file, structName, field string) bool {
52		t.Helper()
53		fset := token.NewFileSet()
54		parsed, err := parser.ParseFile(fset, file, nil, parser.AllErrors)
55		if err != nil {
56			t.Fatalf("parse %s: %v", file, err)
57		}
58		var found bool
59		ast.Inspect(parsed, func(n ast.Node) bool {
60			ts, ok := n.(*ast.TypeSpec)
61			if !ok || ts.Name.Name != structName {
62				return true
63			}
64			st, ok := ts.Type.(*ast.StructType)
65			if !ok {
66				return true
67			}
68			for _, f := range st.Fields.List {
69				for _, name := range f.Names {
70					if name.Name == field {
71						found = true
72						return false
73					}
74				}
75			}
76			return false
77		})
78		return found
79	}
